class Solution {
public:
    int findTheDistanceValue(vector<int>& arr1, vector<int>& arr2, int d) {
        const int OFFSET = 1000;
        const int SIZE = 2001;
        int present[SIZE] = {0};
        for (int x : arr2) present[x + OFFSET] = 1;
        int prefix[SIZE + 1];
        prefix[0] = 0;
        for (int i = 0; i < SIZE; i++) prefix[i + 1] = prefix[i] + present[i];
        int ans = 0;
        for (int v : arr1) {
            int lo = v - d + OFFSET;
            int hi = v + d + OFFSET;
            if (lo < 0) lo = 0;
            if (hi > SIZE - 1) hi = SIZE - 1;
            int count = (lo > hi) ? 0 : (prefix[hi + 1] - prefix[lo]);
            if (count == 0) ans++;
        }
        return ans;
    }
};
